// Elige las N búsquedas activas que hace más tiempo que no se ejecutan.
// Entrada: filas de la pestaña Busquedas.
const cfg = $('Config').first().json;
const n = Number(cfg.busquedas_por_ejecucion) || 3;

const filas = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && String(r.consulta || '').trim() && /^s/i.test(String(r.activa ?? 'SI').trim()));

if (!filas.length) {
  throw new Error('La pestaña "Busquedas" no tiene filas activas (activa = SI). Añade al menos una búsqueda.');
}

filas.sort(
  (a, b) =>
    String(a.ultima_ejecucion || '').localeCompare(String(b.ultima_ejecucion || '')) ||
    String(a.id || '').localeCompare(String(b.id || '')),
);

return filas.slice(0, n).map((r) => ({
  json: {
    id: String(r.id || ''),
    sector: String(r.sector || ''),
    zona: String(r.zona || ''),
    consulta: String(r.consulta).trim(),
    veces_ejecutada: Number(r.veces_ejecutada) || 0,
  },
}));

// ---- utilidades comunes (se incrustan en los nodos Code al compilar) ----
function ahoraMadrid() {
  return DateTime.now().setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm');
}

function texto(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

// Escapa texto para mensajes de Telegram con parse_mode = HTML
function escHtml(v) {
  return texto(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// OJO: el sandbox de los nodos Code de n8n NO tiene la clase URL. Usamos regex.
function partesUrl(url) {
  const u = texto(url);
  const m = (/^https?:\/\//i.test(u) ? u : 'http://' + u).match(/^(https?:)\/\/([^/?#:@\s]+)(?::(\d+))?([^?#\s]*)/i);
  if (!m || !/\./.test(m[2])) return null;
  const host = m[2].toLowerCase();
  return { protocolo: m[1].toLowerCase(), host, origen: m[1].toLowerCase() + '//' + host + (m[3] ? ':' + m[3] : ''), ruta: m[4] || '/' };
}

function dominioDe(url) {
  const p = partesUrl(url);
  return p ? p.host.replace(/^www\d?\./, '') : '';
}

// Resuelve un href (absoluto, //host, /ruta o relativo) contra la URL base.
function resolverUrl(href, base) {
  const h = texto(href);
  const b = partesUrl(base);
  if (!h || !b) return '';
  if (/^https?:\/\//i.test(h)) return h;
  if (h.startsWith('//')) return b.protocolo + h;
  let ruta = h.startsWith('/') ? h : b.ruta.replace(/[^/]*$/, '') + h;
  const [camino, resto = ''] = ruta.split(/(?=[?#])/);
  const segs = [];
  for (const s of camino.split('/')) {
    if (s === '..') segs.pop();
    else if (s !== '.') segs.push(s);
  }
  ruta = segs.join('/');
  return b.origen + (ruta.startsWith('/') ? '' : '/') + ruta + resto;
}

// ¿El dominio o el email está en la pestaña Bloqueados? (acepta emails y dominios)
// Un dominio genérico (gmail.com, hotmail.com…) nunca bloquea a todos sus usuarios:
// para esos solo cuenta el email exacto.
const DOMINIOS_GENERICOS = /^(gmail\.com|googlemail\.com|hotmail\.(com|es)|outlook\.(com|es)|live\.(com|es)|yahoo\.(com|es)|icloud\.com|me\.com|msn\.com|telefonica\.net|movistar\.es|ono\.com|terra\.es|aol\.com|protonmail\.com|proton\.me)$/i;
function estaBloqueado(valor, bloqueados) {
  const v = texto(valor).toLowerCase();
  if (!v) return false;
  const dom = v.includes('@') ? v.split('@').pop() : v;
  return bloqueados.some((b) => b === v || (!DOMINIOS_GENERICOS.test(b) && (b === dom || dom.endsWith('.' + b))));
}

// Convierte los resultados de Google Places en leads nuevos:
//  - solo negocios operativos y con web propia
//  - sin repetir place_id ni dominio ya presentes en el CRM
//  - sin dominios de la pestaña Bloqueados
//  - como máximo max_leads_por_ejecucion
const cfg = $('Config').first().json;
const maxLeads = Number(cfg.max_leads_por_ejecucion) || 15;
const busquedas = $('Elegir búsquedas').all();
const existentes = $('Leer Leads').all().map((i) => i.json || {});
const bloqueados = $('Leer Bloqueados')
  .all()
  .map((i) => texto(i.json && i.json.valor).toLowerCase())
  .filter(Boolean);

const placeIds = new Set(existentes.map((r) => texto(r.place_id)).filter(Boolean));
const dominios = new Set(existentes.map((r) => dominioDe(r.web)).filter(Boolean));
const idsUsados = new Set(existentes.map((r) => texto(r.lead_id)).filter(Boolean));

const NO_ES_WEB_PROPIA = /(^|\.)(facebook\.com|instagram\.com|fb\.com|fb\.me|linktr\.ee|wa\.me|whatsapp\.com|business\.site|google\.com|goo\.gl|g\.page|sites\.google\.com|tiktok\.com|youtube\.com|linkedin\.com|twitter\.com|x\.com|doctoralia\.es|treatwell\.es|booksy\.com|milanuncios\.com|idealista\.com|fotocasa\.es|paginasamarillas\.es)$/i;

const ALFABETO = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function nuevoId() {
  let id;
  do {
    id = ALFABETO[Math.floor(Math.random() * 24)]; // primera letra siempre alfabética
    for (let k = 0; k < 5; k++) id += ALFABETO[Math.floor(Math.random() * ALFABETO.length)];
  } while (idsUsados.has(id));
  idsUsados.add(id);
  return id;
}

const entradas = $input.all();
const errores = entradas.filter((it) => it.json && it.json.error);
if (entradas.length && errores.length === entradas.length) {
  const e = errores[0].json.error;
  throw new Error('Google Places falló en todas las búsquedas: ' + (e.message || JSON.stringify(e)).slice(0, 400));
}

const salida = [];
entradas.forEach((item, i) => {
  const b = (busquedas[i] && busquedas[i].json) || {};
  const places = Array.isArray(item.json && item.json.places) ? item.json.places : [];
  for (const p of places) {
    if (salida.length >= maxLeads) return;
    if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
    const web = texto(p.websiteUri);
    const dom = dominioDe(web);
    if (!web || !dom || NO_ES_WEB_PROPIA.test(dom)) continue;
    if (placeIds.has(texto(p.id)) || dominios.has(dom)) continue;
    if (estaBloqueado(dom, bloqueados)) continue;
    placeIds.add(texto(p.id));
    dominios.add(dom);
    salida.push({
      json: {
        lead_id: nuevoId(),
        empresa: texto(p.displayName && p.displayName.text),
        sector: b.sector || '',
        zona: b.zona || '',
        web,
        dominio: dom,
        telefono: texto(p.nationalPhoneNumber || p.internationalPhoneNumber),
        direccion: texto(p.formattedAddress),
        google_maps_url: texto(p.googleMapsUri),
        place_id: texto(p.id),
        rating: p.rating ?? '',
        num_resenas: p.userRatingCount ?? '',
        categoria_google: texto(p.primaryTypeDisplayName && p.primaryTypeDisplayName.text),
        busqueda_origen: b.consulta || '',
      },
    });
  }
});

return salida;

