const admiteForzado = /^claude-(opus|sonnet|haiku)-4/.test(modelo);

const body = {
  model: modelo,
  max_tokens: 8000,
  system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
  tools: [herramienta],
  tool_choice: admiteForzado ? { type: 'tool', name: 'registrar_analisis' } : { type: 'auto' },
